import React, { useState } from 'react';
import { fmtPhone } from '../utils/helpers';
import { Icons } from '../components/ui/Icons';

export function LoginModal({ onClose, onRegister, toast }) {
    const [phone, setPhone] = useState("");
    const [pass, setPass] = useState("");
    const [loading, setLoading] = useState(false);

    const submit = async () => {
        if (!phone || !pass) return;
        setLoading(true);
        await new Promise(r => setTimeout(r, 900));
        setLoading(false);
        if (pass.length < 3) {
            toast.err("Неверный номер или пароль");
            return;
        }
        toast.ok("Добро пожаловать! 👋");
        onClose();
    };

    return (
        <div className="modal-ov" onClick={e => e.target === e.currentTarget && onClose()}>
            <div className="modal">
                <div className="m-hdr">
                    <div className="m-ttl">
                        <span className="ico">◈</span>Вход
                    </div>
                    <button className="m-x" onClick={onClose}>
                        ✕
                    </button>
                </div>
                <div className="m-body">
                    <div className="fg">
                        <div className="fl">
                            <Icons.Phone />
                            Номер телефона
                        </div>
                        <input
                            className="fi"
                            type="tel"
                            placeholder="+7 (___) ___-__-__"
                            value={phone}
                            onChange={e => setPhone(fmtPhone(e.target.value))}
                        />
                    </div>
                    <div className="fg">
                        <div className="fl">
                            <Icons.Lock />
                            Пароль
                        </div>
                        <input
                            className="fi"
                            type="password"
                            placeholder="Введите пароль"
                            value={pass}
                            onChange={e => setPass(e.target.value)}
                            onKeyDown={e => e.key === "Enter" && submit()}
                        />
                    </div>
                    <button
                        className="submit"
                        onClick={submit}
                        disabled={loading || !phone || !pass}
                    >
                        {loading ? "Входим..." : "Войти"}
                    </button>
                </div>
                <div className="m-ftr">
                    <p>
                        Нет аккаунта? <a onClick={onRegister}>Зарегистрироваться</a>
                    </p>
                    <p>
                        <a>Забыли пароль?</a>
                    </p>
                </div>
            </div>
        </div>
    );
}
